export function getQuestions(theme: ThemeId, level: Level, subcategory?: string): Question[] {
  let pool = QUESTIONS.filter((q) => q.theme === theme && q.level === level)
  
  if (subcategory && subcategory !== 'all') {
    pool = pool.filter((q) => q.subcategory === subcategory)
  }
  return [...pool]
    .sort(() => Math.random() - 0.5)
    .slice(0, 10)
    .map((q) => ({
      ...q,
      options: [...q.options].sort(() => Math.random() - 0.5),
    }))
}
